private void startSsdpServer(Context context) {
    final SettingsNet.WifiProxy wifiProxy = SettingsNet.getWifiProxy(context, null);
    Announcer announcer = new Announcer(wifiProxy, Constants.LAN_DISCOVERY_PORT, "discovery.ultrabar");
    announcer.setMulticast(true);
    announcer.setPeriod(15);
    announcer.setUnit(TimeUnit.SECONDS);
    Objects.requireNonNull(wifiProxy);
    try {
        new DeviceAnnouncer(announcer, new GetInetAddress() { // from class: com.ultrabar.launch.common.init.CommunicationInitializationTask$$ExternalSyntheticLambda0
            @Override // com.ultrabar.comm.listener.GetInetAddress
            public final String getIP() {
                return wifiProxy.getIP();
            }
        }).start();
    } catch (Throwable th) {
        th.printStackTrace();
    }
}
